// Coordinator scope confirmation only; final approval and start remain separate.
let teamScopeContext=null,teamScopeGeneration=0,teamScopeLock=null;
function resetTeamScopeClient(){teamScopeContext=null;teamScopeGeneration++;if(teamScopeLock){teamScopeLock=null;lockShared(false)}}
function cleanTeamScopePreview(v){
 const p=v.scopePreview;if(!p)return null;const id=x=>typeof x==='string'&&/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(x),pos=x=>Number.isSafeInteger(x)&&x>0;
 if(!v.roles.includes('COORDINATOR')||v.mentorStatus!=='ACCEPTED'||!v.consultation.required||v.consultation.scopeConfirmed||v.consultation.requested||v.consultation.declined||v.consultation.stale||!id(p.assignmentId)||!pos(p.assignmentVersion)||!Number.isSafeInteger(p.expectedScopeVersion)||p.expectedScopeVersion<0||typeof p.previewToken!=='string'||!/^[a-f0-9]{64}$/.test(p.previewToken)||!Array.isArray(p.departmentIds)||!p.departmentIds.length||p.departmentIds.length>100||!p.departmentIds.every(id)||new Set(p.departmentIds).size!==p.departmentIds.length||!Array.isArray(p.consultations)||p.consultations.length!==p.departmentIds.length||new Set(p.consultations.map(q=>q.consultationId)).size!==p.consultations.length||p.consultations.length!==v.consultation.accepted||!p.consultations.every((q,i)=>id(q.consultationId)&&pos(q.consultationVersion)&&q.departmentId===p.departmentIds[i]&&id(q.reviewer)&&q.state==='ACCEPTED'&&['responsibility','deliverable'].every(k=>typeof q[k]==='string'&&q[k].trim().length>0&&q[k].length<=2000)&&typeof q.due==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(q.due)&&Number.isFinite(Date.parse(q.due))&&new Date(q.due).toISOString().slice(0,10)===q.due))throw Error('Consultation scope preview changed.');
 return {assignmentId:p.assignmentId,assignmentVersion:p.assignmentVersion,expectedScopeVersion:p.expectedScopeVersion,previewToken:p.previewToken,departmentIds:[...p.departmentIds],consultations:p.consultations.map(q=>Object.fromEntries(['consultationId','consultationVersion','departmentId','reviewer','responsibility','deliverable','due','state'].map(k=>[k,q[k]])))};
}
function bindTeamScopePreview(v,d){teamScopeContext=null;teamScopeGeneration++;const preview=cleanTeamScopePreview(v);if(preview)teamScopeContext={...d,preview}}
const teamScopePriorDetail=teamApprovalDetail;
teamApprovalDetail=function(v){const html=teamScopePriorDetail(v),p=cleanTeamScopePreview(v);if(!p)return html;const form=`<h3>Confirm required consultation scope</h3><p>Review the complete current department responsibilities below. If another department is required, issue its request and obtain acceptance before confirming.</p>${tableHTML(['Department','Representative','Version','Responsibility','Deliverable','Due'],p.consultations.map(q=>[esc(q.departmentId),esc(q.reviewer),q.consultationVersion,esc(q.responsibility),esc(q.deliverable),esc(q.due)]))}<form id="team-scope-confirm-form"><label>Confirmation reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirmed" value="yes" required> I confirm these are the complete department consultation responsibilities required for this proposal and have reviewed their current acceptance.</label><p>Earlier confirmations are retained. Changes require fresh confirmation. This does not record final approval, completed deliverables or permission to start.</p><button type="submit">Confirm consultation scope</button></form>`;return html.replace(/<\/section>$/,form+'</section>')};
function teamScopeCurrent(d){return teamScopeContext===d&&intakeMentorClientCurrent(d.context)&&currentTeamApprovalQueue()===d.queue}
async function submitTeamScopeConfirmation(fields){
 const d=teamScopeContext;if(!d||sharedBusy||!teamScopeCurrent(d)||!$('#modal').open||document.querySelector('#team-approval-detail')!==d.marker)return toast('Refresh and reopen the current consultation scope.');
 if(!fields||Object.keys(fields).some(k=>!['reason','confirmed'].includes(k))||fields.confirmed!=='yes'||typeof fields.reason!=='string'||!fields.reason.trim()||fields.reason.trim().length>2000)return toast('Provide a reason and explicitly confirm the consultation scope.');
 const c=d.context,p=d.preview,token={},generation=++teamScopeGeneration;teamScopeLock=token;lockShared(true);
 try{const r=await sharedFetch('/api/workspace',{command:'confirmIntakeTeamConsultationScope',actor:c.actor,revision:c.revision,args:[{proposalId:d.item.proposalId,firstReviewId:d.item.firstReviewId,submissionVersion:d.item.submissionVersion,assignmentId:p.assignmentId,assignmentVersion:p.assignmentVersion,departmentIds:[...p.departmentIds],expectedScopeVersion:p.expectedScopeVersion,previewToken:p.previewToken,reason:fields.reason.trim(),confirm:true}],context:{page:'Activity Intake'}});if(generation!==teamScopeGeneration||!teamScopeCurrent(d))return;
  const s=r?.scope;if(r?.kind!=='INTAKE_TEAM_COMMAND'||r.action!=='CONSULTATION_SCOPE'||r.actor!==c.actor||r.revision!==c.revision+1||!s||['proposalId','firstReviewId','submissionVersion'].some(k=>s[k]!==d.item[k])||typeof s.scopeId!=='string'||!/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(s.scopeId)||s.scopeVersion!==p.expectedScopeVersion+1||s.state!=='CONFIRMED'||s.workspaceRevision!==r.revision||s.executionAuthorized!==false)throw Error('Scope confirmation response changed.');
  const fresh=await sharedFetch('/api/workspace');if(generation!==teamScopeGeneration||!teamScopeCurrent(d))return;if(fresh?.actor!==c.actor||!Number.isSafeInteger(fresh.revision)||fresh.revision<r.revision||!Array.isArray(fresh.data?.projects))throw Error('A fresh workspace is required.');closeModal();resetTeamApprovalClient();applyShared(fresh);toast('Consultation scope confirmed. Final approval and permission to start remain separate.');
 }catch(e){if(generation===teamScopeGeneration&&teamScopeCurrent(d)){closeModal();resetTeamApprovalClient();toast('Unable to confirm scope. Refresh the workspace and check its status before trying again.')}}finally{if(teamScopeLock===token){teamScopeLock=null;lockShared(false)}}
}
const teamScopePriorReset=resetTeamApprovalClient;resetTeamApprovalClient=function(){resetTeamScopeClient();return teamScopePriorReset()};
document.addEventListener('submit',event=>{if(event.target?.id!=='team-scope-confirm-form')return;event.preventDefault();submitTeamScopeConfirmation(Object.fromEntries(new FormData(event.target)))});
